 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"

/* Include the Exo-generated kernel header. */
#include "generated/3mm/3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GEMM kernel: C[M, N] = A[M, K] * B[K, N]
@proc
def gemm_base(
    M: size,
    N: size,
    K: size,
    A: DATA_TYPE[M, K] @ DRAM,
    B: DATA_TYPE[K, N] @ DRAM,
    C: DATA_TYPE[M, N] @ DRAM,
):
    # Naive row-major GEMM: good locality for A and C, but B accesses are strided.
    for i in seq(0, M):
        for j in seq(0, N):
            C[i, j] = 0.0
            for k in seq(0, K):
                C[i, j] += A[i, k] * B[k, j]

# Schedule GEMM for better cache locality and parallelism.
gemm_opt = gemm_base

# Reorder inner loops from (j, k) to (k, j):
# After this, for each row i we iterate over k first, then sweep j.
# This streams B's rows (B[k, :]) contiguously in memory and still
# preserves the accumulation order over k for each C[i, j].
gemm_opt = reorder_loops(gemm_opt, "j k")

# Parallelize the outermost loop over rows of C. Different i-rows are
# independent, so this exposes coarse-grain parallelism (e.g., via OpenMP).
gemm_opt = parallelize_loop(gemm_opt, "i")

# Give the scheduled GEMM a stable, readable name.
gemm = rename(gemm_opt, "gemm")

# 3mm driver kernel built from three GEMMs:
#   E = A * B
#   F = C * D
#   G = E * F
@proc
def kernel_3mm_base(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
):
    # E := A * B  (ni x nk) * (nk x nj)
    gemm(ni, nj, nk, A, B, E)

    # F := C * D  (nj x nm) * (nm x nl)
    gemm(nj, nl, nm, C, D, F)

    # G := E * F  (ni x nj) * (nj x nl)
    gemm(ni, nl, nj, E, F, G)

# Export the scheduled 3mm kernel under the name expected by the C driver.
kernel_3mm = rename(kernel_3mm_base, "kernel_3mm")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_3mm (/*ctxt=*/NULL, ni, nj, nk, nl, nm,
              (DATA_TYPE*)POLYBENCH_ARRAY(E),
              (DATA_TYPE*)POLYBENCH_ARRAY(A),
              (DATA_TYPE*)POLYBENCH_ARRAY(B),
              (DATA_TYPE*)POLYBENCH_ARRAY(F),
              (DATA_TYPE*)POLYBENCH_ARRAY(C),
              (DATA_TYPE*)POLYBENCH_ARRAY(D),
              (DATA_TYPE*)POLYBENCH_ARRAY(G));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(G)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(E);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(F);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);
  POLYBENCH_FREE_ARRAY(G);

  return 0;
}
