# The object code is already written in a cache-friendly loop order:
#   - Each GEMM zeroes its output matrix first.
#   - Then it uses an (i, k, j) loop nest so that:
#       * A/C/E rows are reused across the inner j loop.
#       * B/D/F rows are streamed contiguously in the inner j loop.
@proc
def kernel_3mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
