        for j_e_init in seq(0, nj):
            E[i_e_init, j_e_init] = 0.0

    for i_e in seq(0, ni):
        for k_e in seq(0, nk):
            # Reuse A[i_e, k_e] across the entire row of B[k_e, :]
            a_ik: DATA_TYPE
            a_ik = A[i_e, k_e]
            for j_e in seq(0, nj):
                E[i_e, j_e] += a_ik * B[k_e, j_e]

