    for i_f_init in seq(0, nj):
        for j_f_init in seq(0, nl):
            F[i_f_init, j_f_init] = 0.0

    for i_f in seq(0, nj):
        for k_f in seq(0, nm):
            # Reuse C[i_f, k_f] across the entire row of D[k_f, :]
            c_ik: DATA_TYPE
            c_ik = C[i_f, k_f]
            for j_f in seq(0, nl):
                F[i_f, j_f] += c_ik * D[k_f, j_f]

    # G := E * F
    for i_g_init in seq(0, ni):
        for j_g_init in seq(0, nl):
            G[i_g_init, j_g_init] = 0.0

