# expose long, contiguous strides for the compiler's vectorizer.
kernel_3mm = divide_loop(kernel_3mm, "j_e", TJ_E, ("jo_e", "ji_e"), tail="guard")
kernel_3mm = divide_loop(kernel_3mm, "j_f", TJ_F, ("jo_f", "ji_f"), tail="guard")
kernel_3mm = divide_loop(kernel_3mm, "j_g", TJ_G, ("jo_g", "ji_g"), tail="guard")

