kernel_3mm = parallelize_loop(kernel_3mm, kernel_3mm.find_loop("i_e"))
kernel_3mm = parallelize_loop(kernel_3mm, kernel_3mm.find_loop("i_f"))
kernel_3mm = parallelize_loop(kernel_3mm, kernel_3mm.find_loop("i_g"))

# Clean up any trivial loops or expressions created by tiling.
kernel_3mm = simplify(kernel_3mm)
