    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
):
    # E := A * B   (ni x nk) * (nk x nj) -> (ni x nj)
    gemm(ni, nj, nk, A, B, E)

    # F := C * D   (nj x nm) * (nm x nl) -> (nj x nl)
    gemm(nj, nl, nm, C, D, F)

